#!/bin/bash
# R2 prototype runs: M2 (stapled per-token ML-DSA-44, b5s) vs B1, pooled EMBER (o1, tree 32) and B5,
# plus recovery (p4) for M2 and EMBER staple-all.  Outputs: results/proto_*_r2.csv, raw/proto_r2/.
#   STAGES="p1 p1tb p2 p4" RUNS=5 bash run_r2.sh
# Cores: edge 1 (GOMAXPROCS=1); tapbridges 2; issuer 3; loadgen 0 (P1 loopback: 0,2,3; P1-tb/P2: 0,3).
# Do NOT edit this file while it runs.
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
RES=${RES:-$(cd "$HERE/../../results" && pwd)}
RAW=$RES/raw/proto_r2; mkdir -p "$RAW"
BIN=$HERE/bin
STAGES=${STAGES:-"p1 p1tb p2 p4"}
RUNS=${RUNS:-5}
SCHEMES=${SCHEMES:-"b1 b5s o1 b5"}
TREE=${TREE:-32}                  # pooled EMBER tree size (paper: ~20 tokens per 10 ms pool at 2000/s)
P1_DUR=${P1_DUR:-20s}; P1_WARM=${P1_WARM:-5s}
TB_DUR=${TB_DUR:-15s}; TB_WARM=${TB_WARM:-3s}
P2_DUR=${P2_DUR:-15s}; P2_WARM=${P2_WARM:-3s}
P4_DUR=${P4_DUR:-30s}; P4_TCUT=${P4_TCUT:-8s}; P4_EVENT_AT=${P4_EVENT_AT:-15}
P4_SCEN=${P4_SCEN:-"cold evict64 evict256 flush restart"}; P4_PMOVE=${P4_PMOVE:-0.01}
export GOTOOLCHAIN=local GOFLAGS=-mod=mod
cd "$HERE"
for c in edge issuer loadgen; do /usr/local/go/bin/go build -o bin/$c ./$c; done
gcc -O2 -Wall -o bin/tapbridge netemu/tapbridge.c
log() { echo "[$(date +%H:%M:%S)] $*" | tee -a "$RAW/run_r2.log"; }
( while true; do echo "== $(date +%H:%M:%S) load=$(cut -d' ' -f1-3 /proc/loadavg) steal=$(awk '/^cpu /{print $9}' /proc/stat)"; \
  ps -eo pcpu,psr,comm --sort=-pcpu | awk 'NR>1 && $1>5' | grep -v -E "edge|issuer|loadgen|tapbridge" || true; sleep 15; done ) >> "$RAW/interference.log" 2>&1 &
SAMPLER=$!
trap 'kill $SAMPLER 2>/dev/null || true' EXIT
ensure_net() {
  if ! { ip netns exec ember_cli true && ip netns exec ember_edge true && ip netns exec ember_origin true \
         && pgrep -f "bin/tapbridge tAc" >/dev/null && pgrep -f "bin/tapbridge tBe" >/dev/null; } 2>/dev/null; then
    bash netemu/net3.sh down >/dev/null 2>&1 || true
    bash netemu/net3.sh up 2 | tee -a "$RAW/run_r2.log"
  fi
}
killall_procs() { pkill -f "$BIN/edge " 2>/dev/null || true; pkill -f "$BIN/issuer " 2>/dev/null || true; sleep 0.3; }
wait_http() { for i in $(seq 100); do ip netns exec "$1" curl -s -o /dev/null "$2" && return 0; sleep 0.1; done; echo "timeout $2"; return 1; }
edgepid() { pgrep -f "$BIN/edge -listen $1" | head -1; }
ensure_net

for st in $STAGES; do case $st in
p1)
  log "P1 (edge-ns loopback) schemes=$SCHEMES tree=$TREE warm=$P1_WARM dur=$P1_DUR runs=$RUNS"
  rm -f "$RES/proto_capacity_r2.csv"
  for r in $(seq 1 $RUNS); do for s in $SCHEMES; do
    ip netns exec ember_edge env GOMAXPROCS=1 taskset -c 1 $BIN/edge -listen 127.0.0.1:8080 > "$RAW/p1_edge_${s}_$r.log" 2>&1 &
    wait_http ember_edge http://127.0.0.1:8080/ping
    ip netns exec ember_edge taskset -c 0,2,3 $BIN/loadgen -mode p1 -target 127.0.0.1:8080 -scheme $s -conns 64 -K 150 -tree $TREE \
      -sessions 8000 -warm $P1_WARM -dur $P1_DUR -edgepid $(edgepid 127.0.0.1:8080) -run $r -net netns-loopback-edge \
      -out "$RES/proto_capacity_r2.csv" 2>>"$RAW/p1_loadgen.log"
    ip netns exec ember_edge curl -s http://127.0.0.1:8080/stats > "$RAW/p1_stats_${s}_$r.json" || true
    killall_procs
  done; done
  ;;
p1tb)
  log "P1 over tapbridge A (cli -> edge, 20 ms RTT), 512 conns, warm=$TB_WARM dur=$TB_DUR runs=$RUNS"
  rm -f "$RES/proto_capacity_tb_r2.csv"
  for r in $(seq 1 $RUNS); do for s in $SCHEMES; do
    ip netns exec ember_edge env GOMAXPROCS=1 taskset -c 1 $BIN/edge -listen 10.71.0.1:8080 > "$RAW/p1tb_edge_${s}_$r.log" 2>&1 &
    wait_http ember_cli http://10.71.0.1:8080/ping
    ip netns exec ember_cli taskset -c 0,3 $BIN/loadgen -mode p1 -target 10.71.0.1:8080 -scheme $s -conns 512 -K 150 -tree $TREE \
      -sessions 8000 -warm $TB_WARM -dur $TB_DUR -edgepid $(edgepid 10.71.0.1:8080) -run $r -net netns-tapbridge \
      -out "$RES/proto_capacity_tb_r2.csv" 2>>"$RAW/p1tb_loadgen.log"
    killall_procs
  done; done
  ;;
p2)
  log "P2 open loop over tapbridge at 50%/80% of the r2 P1 (loopback) capacity"
  rm -f "$RES/proto_latency_runs_r2.csv"
  for r in $(seq 1 $RUNS); do for frac in 0.5 0.8; do for s in $SCHEMES; do
    CAP=$(awk -F, -v s=$s 'NR>1 && $1==s {t+=$3; n++} END {if (n) printf "%.1f", t/n}' "$RES/proto_capacity_r2.csv")
    RATE=$(awk -v c=$CAP -v f=$frac 'BEGIN{printf "%.1f", c*f}')
    ip netns exec ember_edge env GOMAXPROCS=1 taskset -c 1 $BIN/edge -listen 10.71.0.1:8080 > "$RAW/p2_edge_${s}_${frac}_$r.log" 2>&1 &
    wait_http ember_cli http://10.71.0.1:8080/ping
    ip netns exec ember_cli taskset -c 0,3 $BIN/loadgen -mode p2 -target 10.71.0.1:8080 -scheme $s -conns 1024 -K 150 -tree $TREE \
      -sessions 8000 -rate $RATE -loadfrac $frac -warm $P2_WARM -dur $P2_DUR -run $r -net netns-tapbridge \
      -out "$RES/proto_latency_runs_r2.csv" 2>>"$RAW/p2_loadgen.log"
    killall_procs
  done; done; done
  ;;
p4)
  log "P4 recovery: M2 vs EMBER staple-all (pooled, delta 100 ms), lambda 200 each, V=10, pmove=$P4_PMOVE, scenarios=$P4_SCEN"
  rm -f "$RES/proto_recovery_r2.csv"
  for r in $(seq 1 $RUNS); do for sc in $P4_SCEN; do
    EFLAGS="-listen 10.71.0.1:8080 -origin http://10.72.0.2:9090 -ember-miss 401 -prewarm 8"
    case $sc in evict*) CAP=${sc#evict}; EFLAGS="$EFLAGS -scache-cap $CAP -rcache-cap $CAP";; esac
    EV=none; [ "$sc" = flush ] && EV=flush; [ "$sc" = restart ] && EV=restart
    ip netns exec ember_origin taskset -c 3 $BIN/issuer -listen 10.72.0.2:9090 -kids 12:100 -m2kids 11 > "$RAW/p4_issuer_${sc}_$r.log" 2>&1 &
    wait_http ember_edge http://10.72.0.2:9090/ping
    ip netns exec ember_edge env GOMAXPROCS=1 taskset -c 1 $BIN/edge $EFLAGS > "$RAW/p4_edge_${sc}_$r.log" 2>&1 &
    wait_http ember_cli http://10.71.0.1:8080/ping
    ip netns exec ember_cli taskset -c 0 $BIN/loadgen -mode p4 -target 10.71.0.1:8080 -issuer http://10.72.0.2:9090 \
      -p4pipes m2:200:11,ember:200:12 -V 10 -alpha 0.8 -kmean 20 -seg 200ms -first-med-ms 120 -first-sigma 0.5 \
      -pmove $P4_PMOVE -dur $P4_DUR -tcut $P4_TCUT -event $EV -event-at ${P4_EVENT_AT}s -scenario $sc -run $r -seed 20261105 \
      -net netns-tapbridge -out "$RES/proto_recovery_r2.csv" -reqlog "$RAW/p4_req_${sc}_r$r.csv" 2>>"$RAW/p4_loadgen.log" &
    LG=$!
    if [ "$sc" = restart ]; then
      sleep $P4_EVENT_AT
      echo "restart at $(date +%s.%N)" >> "$RAW/p4_restart_times.txt"
      pkill -f "$BIN/edge " || true
      ip netns exec ember_edge env GOMAXPROCS=1 taskset -c 1 $BIN/edge $EFLAGS > "$RAW/p4_edge_${sc}_${r}_after.log" 2>&1 &
    fi
    wait $LG
    gzip -f "$RAW/p4_req_${sc}_r$r.csv"
    killall_procs
  done; done
  ;;
esac; done
log "done: $STAGES"
